code.source:
#include <iostream>
using namespace std;

class Account {
protected:
    double balance_ = 100;
};

class Savings : public Account {
public:
    void add_interest() { balance_ *= 1.1; }
    double balance() const { return balance_; }
};

int main() {
    Savings s;
    s.add_interest();
    cout << s.balance() << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Base {
public:
    int open_ = 1;

protected:
    int family_ = 2;

private:
    int secret_ = 3;

public:
    int secret() const { return secret_; }
};

class Child : public Base {
public:
    int sum() const { return open_ + family_ + secret(); }
};

int main() {
    Child c;
    cout << c.sum() << endl;
    cout << c.open_ << endl;
    return 0;
}

